import{_ as a,C as c,o as e,c as n,a2 as o,b as r,w as d,a as l,E as i,a3 as p}from"./chunks/framework.CCXDMzJr.js";const f=JSON.parse('{"title":"第 3 章 总体架构","description":"","frontmatter":{},"headers":[],"relativePath":"ch3-architecture.md","filePath":"ch3-architecture.md","lastUpdated":null}'),h={name:"ch3-architecture.md"};function u(g,t,m,b,x,_){const s=c("Mermaid");return e(),n("div",null,[t[1]||(t[1]=o('<h1 id="第-3-章-总体架构" tabindex="-1">第 3 章 总体架构 <a class="header-anchor" href="#第-3-章-总体架构" aria-label="Permalink to &quot;第 3 章 总体架构&quot;">​</a></h1><p>本章是全书的总纲。我们回答三个问题：<strong>为什么&quot;一切皆插件&quot;能成立</strong>、<strong>一个运行的 dsh 是什么</strong>、以及 <strong>能力如何被组织成可替换的接缝</strong>。</p><h2 id="_3-1-一切皆插件-cordis-的承诺" tabindex="-1">3.1 一切皆插件：Cordis 的承诺 <a class="header-anchor" href="#_3-1-一切皆插件-cordis-的承诺" aria-label="Permalink to &quot;3.1 一切皆插件：Cordis 的承诺&quot;">​</a></h2><p>dsh 的架构承诺（<code>docs/architecture.md</code>）：</p><blockquote><p>There is no privileged core to patch: you extend dsh by mounting a plugin beside the others, and registrations are effects that unwind when their plugin unloads.</p></blockquote><p>翻译过来：<strong>不存在需要打补丁的特权核心</strong>。要扩展 dsh，只需在旁边挂载一枚插件；所有注册（服务、事件、工具、提示词分节……）都是&quot;可逆副作用&quot;，插件卸载时自动回卷。</p><p>这个承诺由 Cordis 的四个机制支撑（详见第二部分）：</p><ol><li><strong>Context 即服务仓库</strong>：插件通过 <code>ctx.&lt;key&gt;</code> 找到服务（<code>ctx.tools</code>、<code>ctx.llm</code>、<code>ctx.sessions</code>…），而不是 import 具体实现；</li><li><strong>inject 声明依赖</strong>：插件声明需要的服务，Cordis 让它在依赖就绪后才启动——<strong>装载顺序由依赖关系表达，而不是手工编排</strong>；</li><li><strong>类型化事件</strong>：服务通过声明合并定义事件，以 <code>emit</code> / <code>waterfall</code> / <code>parallel</code> / <code>serial</code> 派发，实现观察、包裹、扇出、串行等语义；</li><li><strong>可逆副作用</strong>：一切注册都挂在 <code>ctx.effect()</code> 上，卸载插件时按注册逆序自动清理。</li></ol><h2 id="_3-2-一个运行的-dsh-profile-与-bundle" tabindex="-1">3.2 一个运行的 dsh：Profile 与 Bundle <a class="header-anchor" href="#_3-2-一个运行的-dsh-profile-与-bundle" aria-label="Permalink to &quot;3.2 一个运行的 dsh：Profile 与 Bundle&quot;">​</a></h2><p>一个运行的 dsh 是<strong>从空根配置开始、按顺序叠加 patch 层而组合出的插件树</strong>。</p>',10)),(e(),r(p,null,{default:d(()=>[i(s,{id:"mermaid-51",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%E7%A9%BA%E6%A0%B9%E9%85%8D%E7%BD%AE%20cordis.yml%20%3D%20%5B%5D%5D%20--%3E%20B%5Bbundle%201%20patch%20%E5%B1%82%5D%0A%20%20%20%20B%20--%3E%20C%5Bbundle%202%20patch%20%E5%B1%82%5D%0A%20%20%20%20C%20--%3E%20D%5B...%20%E6%9B%B4%E5%A4%9A%20bundle%5D%0A%20%20%20%20D%20--%3E%20E%5Bprofile%20%E7%9A%84%20cordis.patch.yml%5D%0A%20%20%20%20E%20--%3E%20F%5B%E7%94%A8%E6%88%B7%E7%BA%A7%20%24DSH_HOME%2Fcordis.patch.yml%5D%0A%20%20%20%20F%20--%3E%20G%5B--patch%20%E8%A6%86%E7%9B%96%E5%B1%82%20%2F%20%E9%81%A5%E6%B5%8B%E5%BC%80%E5%85%B3%5D%0A%20%20%20%20G%20--%3E%20H%5B%E6%9C%80%E7%BB%88%E6%8F%92%E4%BB%B6%E6%A0%91%5D%0A"})]),fallback:d(()=>[...t[0]||(t[0]=[l(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=o(`<p>分层语义（<code>apps/cli/src/profile-boot.ts</code>）：</p><ul><li><strong>Profile（配置档）</strong>：存放在 Harness 主目录（默认 <code>~/.dsh</code>）下的命名组合。<code>dsh.profile</code> 清单字段列出它堆叠的 bundles、持有的外部插件与用户自己的 <code>cordis.patch.yml</code>。<code>web</code> 与 <code>headless</code> 是随附模板；</li><li><strong>Bundle（捆绑包）</strong>：Cordis 配置行 + 它们装载的代码的分发格式，让上层任何 patch 都能覆盖它插入的行。每个 bundle 在自己的 <code>package.json</code> 的 <code>dsh.bundle</code> 字段声明 patch 文件；</li><li><strong>三层内置 bundle</strong>： <ul><li><code>dsh-base</code>：每个 profile 的第一层——模型适配器、工具、持久化、沙箱与审批策略、设置、凭据、遥测；</li><li><code>dsh-web-app</code>：在 base 之上增加浏览器应用；</li><li><code>dsh-headless</code>：无服务器的一次性运行器。</li></ul></li></ul><p><strong>Patch 目标按 id 寻址</strong>：要么整行替换某条配置，要么 <code>insert</code> 新行。想看机器实际启动的树：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dsh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dump-config</span></span></code></pre></div><p>打印出的任何一行，都可以用你自己的 patch 替换。这条命令的实现（<code>renderConfigDump</code>，<code>packages/boot/app-boot/src/index.ts:379</code>）会逐层重放 patch 算法，并在输出中标注每行的来源文件与被哪些层 patch 过。</p><h2 id="_3-3-双平面-host-与-client" tabindex="-1">3.3 双平面：Host 与 Client <a class="header-anchor" href="#_3-3-双平面-host-与-client" aria-label="Permalink to &quot;3.3 双平面：Host 与 Client&quot;">​</a></h2><p>dsh 的运行时横跨两个平面，<strong>各有一棵独立的 Cordis 插件树</strong>：</p><table tabindex="0"><thead><tr><th></th><th>Host</th><th>Client</th></tr></thead><tbody><tr><td>运行位置</td><td>Node.js 进程</td><td>浏览器页面</td></tr><tr><td>能力</td><td>文件、命令、进程、网络、Agent/Session、工具注册</td><td>页面主题、布局、当前页状态、工具卡片</td></tr><tr><td>通信</td><td>—</td><td><code>host.call(method, args)</code> 包私有 JSON RPC（Client→Host）</td></tr></tbody></table><p>Host 侧还有 <code>api-remotes</code>：通过 <code>@Remote</code> 注解把 Host 服务方法暴露给 Client，构建期由 Typert 生成两侧契约与运行时装配（<code>docs/api-gateway.md</code>）。浏览器通过 WebSocket 之类的连接通道与 Host 保持同步（详见第 17 章）。</p><h2 id="_3-4-核心包与-ctx-键" tabindex="-1">3.4 核心包与 ctx 键 <a class="header-anchor" href="#_3-4-核心包与-ctx-键" aria-label="Permalink to &quot;3.4 核心包与 ctx 键&quot;">​</a></h2><p><code>docs/architecture.md</code> 给出核心包的职责矩阵：</p><table tabindex="0"><thead><tr><th>包</th><th>拥有什么</th><th>ctx 键</th></tr></thead><tbody><tr><td><code>core/session</code></td><td>append-only <code>SessionEvent</code> 日志与内存存储</td><td><code>ctx.sessions</code></td></tr><tr><td><code>core/system-prompt</code></td><td>提示词分节与工具 schema 组装</td><td><code>ctx.systemPrompt</code></td></tr><tr><td><code>core/tools</code></td><td>作用域工具注册表与受保护执行管道</td><td><code>ctx.tools</code></td></tr><tr><td><code>core/agent</code></td><td><code>Agent</code> 接口、实时注册表、<code>agent/*</code> 事件</td><td><code>ctx.agents</code></td></tr><tr><td><code>core/agent-loop</code></td><td>实现该接口的默认驱动</td><td><code>ctx.agentLoop</code></td></tr><tr><td><code>core/scope</code></td><td>每代理作用域注册原语</td><td>库，无键</td></tr><tr><td><code>llm/llm</code></td><td>消息与流式词汇 + 适配器接缝</td><td><code>ctx.llm</code></td></tr></tbody></table><h2 id="_3-5-事件-三个领域" tabindex="-1">3.5 事件：三个领域 <a class="header-anchor" href="#_3-5-事件-三个领域" aria-label="Permalink to &quot;3.5 事件：三个领域&quot;">​</a></h2><p>事件是 dsh 的扩展点。<code>docs/architecture.md</code> 把事件分为三个领域，选对领域是多数改动里的第一个决策：</p><ol><li><strong>会话事件（durable facts）</strong>：追加进日志并通过 <code>session/event</code> 广播。当&quot;事实必须跨重载存活&quot;时使用。例如 <code>turn/start</code>、<code>user/message</code>、<code>assistant/message</code>、<code>tool/result</code>；</li><li><strong>Agent 事件（live）</strong>：<code>agent/*</code>，携带活的 <code>Agent</code>：inbox、step、status、request、validation、continuation。用于观察或拦截在途工作；</li><li><strong>能力事件（seam）</strong>：把策略与适配器挂到接缝上（<code>fs/*</code>、<code>tools/*</code>、<code>telemetry/*</code>），不 import 循环。</li></ol><p><strong>关键原则——&quot;模型可见即已记录&quot;（model-visible means logged）</strong>：任何进入模型请求的内容必须能从日志重建，运行时不变式强制这一点。因此，新的模型可见输入必须新增会话事件类型（扩展 <code>SessionEventMap</code> 并从日志渲染），而不是临时拼接。</p><h2 id="_3-6-turn-流程一瞥" tabindex="-1">3.6 Turn 流程一瞥 <a class="header-anchor" href="#_3-6-turn-流程一瞥" aria-label="Permalink to &quot;3.6 Turn 流程一瞥&quot;">​</a></h2><p><strong>step</strong> = 一次模型请求 + 它调用的工具；<strong>turn</strong> = 零或多个 step（打开于首个输入被认领之前，关闭于&quot;无所亏欠&quot;之时）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>turn/start</span></span>
<span class="line"><span>  claim next-step input plus one queued message</span></span>
<span class="line"><span>  assemble prompt sections + tool schemas</span></span>
<span class="line"><span>  -&gt; agent/pre-step                   reject | enter(messages)</span></span>
<span class="line"><span>     step/start</span></span>
<span class="line"><span>     append entered messages as user/message</span></span>
<span class="line"><span>     derive model history from the log</span></span>
<span class="line"><span>     agent/request -&gt; llm/stream -&gt; assistant/chunk* -&gt; assistant/message</span></span>
<span class="line"><span>     tool/call* -&gt; tools/pre-execute -&gt; tools/execute -&gt; tools/post-execute -&gt; tool/result*</span></span>
<span class="line"><span>     step/end</span></span>
<span class="line"><span>  -&gt; agent/turn-stopping</span></span>
<span class="line"><span>turn/end</span></span></code></pre></div><p>其中 <code>turn/*</code>、<code>step/*</code>、<code>user/message</code>、<code>assistant/*</code>、<code>tool/*</code> 是持久会话事件；其余是三个领域的实时扩展点。<code>agent/pre-step</code>、<code>agent/request</code>、<code>llm/stream</code> 与三个 <code>tools/*</code> 事件是 <strong>waterfall</strong>（监听者必须调用 <code>next()</code> 委派），<code>agent/turn-stopping</code> 是串行且没有 <code>next()</code>。第 11 章将逐行追踪这段流程的实现。</p><h2 id="_3-7-能力接缝-三件套模式" tabindex="-1">3.7 能力接缝：三件套模式 <a class="header-anchor" href="#_3-7-能力接缝-三件套模式" aria-label="Permalink to &quot;3.7 能力接缝：三件套模式&quot;">​</a></h2><p>**接缝（seam）**是可替换能力的组织方式，包含三个角色：</p><ol><li><strong>Service Definition</strong>：声明接口；</li><li><strong>Service Provider</strong>：实现它；</li><li><strong>Consumer</strong>：消费它，通常是模型可见的工具。</li></ol><p>一个包可以身兼多角，但<strong>一个角色构不成接缝</strong>——新增能力意味着设计全部三个角色（<code>docs/capability-seams.md</code>）。</p><p>接缝是&quot;一次替换 Provider 改变整个产品&quot;的原因：文件系统与子进程 Provider 共享同一个执行世界，把二者指向远程沙箱，Bash、PTY、LSP 就跟着一起迁移，无需为每个消费者分叉实现。子代理 Provider 同样多变——从全新子 agent 到委托给另一个产品的 turn（第 16 章展开）。</p><h2 id="_3-8-新行为放哪里-官方决策表" tabindex="-1">3.8 新行为放哪里：官方决策表 <a class="header-anchor" href="#_3-8-新行为放哪里-官方决策表" aria-label="Permalink to &quot;3.8 新行为放哪里：官方决策表&quot;">​</a></h2><p><code>docs/architecture.md</code> 的&quot;Where new behavior goes&quot;是扩展 dsh 的第一索引，摘录核心条目：</p><table tabindex="0"><thead><tr><th>目标</th><th>机制</th></tr></thead><tbody><tr><td>添加模型提供商</td><td>在 <code>ctx.llm</code> 注册适配器</td></tr><tr><td>添加模型可见能力</td><td>注册到 <code>ctx.tools</code>；其 schema 加入提示词组装</td></tr><tr><td>给某个会话不同的能力集</td><td>组合一个 agent preset；那里的服务行需要 <code>isolate</code> realm</td></tr><tr><td>添加 shell 执行</td><td>注册 <code>ctx.shell</code> 后端；本地实现经 <code>ctx.subprocess</code> 派生进程</td></tr><tr><td>添加人类命令</td><td>注册到 <code>ctx.commands</code>，不经模型 turn 直接派发</td></tr><tr><td>添加后台工作</td><td>注册到 <code>ctx.jobs</code>；<code>job_*</code> 工具收集/停止它们</td></tr><tr><td>拦截请求/工具/turn</td><td>使用其 <code>agent/*</code> 或 <code>tools/*</code> 事件</td></tr><tr><td>添加模型可见上下文</td><td>调用 <code>agent.inject()</code>，落在下一次被接纳的请求里</td></tr><tr><td>添加 UI / 编辑器集成</td><td>驱动 <code>ctx.agents</code>，从 <code>session/event</code> 渲染</td></tr><tr><td>添加持久会话状态</td><td>扩展 <code>SessionEventMap</code>，从日志渲染与重放</td></tr><tr><td>分叉活会话</td><td><code>ctx.sessions.fork(source, boundary?, childSessionId?)</code></td></tr><tr><td>把注册作用域限制到一个 agent</td><td>使用该 agent 的 <code>agent.ctx</code></td></tr></tbody></table><h2 id="_3-9-小结" tabindex="-1">3.9 小结 <a class="header-anchor" href="#_3-9-小结" aria-label="Permalink to &quot;3.9 小结&quot;">​</a></h2><ul><li>dsh = 空根 + 分层 patch 组合出的插件树（Profile/Bundle）；</li><li>两个平面（Host/Client）各有一棵 Cordis 树，通过 RPC 通信；</li><li>核心能力以 <code>ctx</code> 服务 + 三领域事件呈现；</li><li>可替换能力以&quot;定义/提供者/消费者&quot;三件套组织；</li><li>&quot;模型可见即已记录&quot;是会话层的不变式。</li></ul><p>接下来的第二部分，我们从 vendored Cordis 源码开始，把&quot;插件树&quot;这个抽象彻底拆开。</p>`,31))])}const B=a(h,[["render",u]]);export{f as __pageData,B as default};
